5	
6	// AscendC RotaryMul kernel
7	// Operator: npu_rotary_mul (Rotary Position Embedding Multiply)
8	// Computes: output = input * r1 + rotated * r2
9	//   half mode:       rotated = concat(-input[:,half_d:], input[:,:half_d])
10	//   interleave mode: rotated[i] = interleave(-input[1::2], input[0::2])
11	// All compute in FP32 for numerical stability.
12	// Pure Vector operator, no Cube.
13	
14	#include "kernel_operator.h"
15	
16	using namespace AscendC;
17	
18	constexpr int32_t BUFFER_NUM = 1;
19	constexpr int32_t MAX_D = 256;
20	
21	// ---------------------------------------------------------------------------
22	// Data movement helpers
23	// ---------------------------------------------------------------------------
24	
25	template <typename T>
26	__aicore__ inline void LoadGmToUb(
27	    LocalTensor<T> &dst,
28	    const GlobalTensor<T> &src,
29	    int32_t count)
30	{
31	    if (count <= 0) { return; }
32	    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
33	    DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
34	    DataCopyPad(dst, src, copyParams, padParams);
35	}
36	
37	template <typename T>
38	__aicore__ inline void StoreUbToGm(
39	    const GlobalTensor<T> &dst,
40	    const LocalTensor<T> &src,
41	    int32_t count)
42	{
43	    if (count <= 0) { return; }
44	    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
45	    DataCopyPad(dst, src, copyParams);
46	}
47	
48	// ---------------------------------------------------------------------------
49	// Output cast mode helper
50	// ---------------------------------------------------------------------------
51	
52	template <typename T>
53	__aicore__ inline RoundMode OutputCastMode()
54	{
55	    if constexpr (std::is_same_v<T, bfloat16_t>) {
56	        return RoundMode::CAST_ROUND;
57	    }
58	    return RoundMode::CAST_NONE;
59	}
60	
61	// ---------------------------------------------------------------------------
62	// RotaryMul Kernel
63	// ---------------------------------------------------------------------------
64	
65	template <typename dataType>
66	class KernelRotaryMul {
67	public:
68	    __aicore__ inline void Init(
69	        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
70	        int64_t total_rows, int64_t D, int64_t half_d,
71	        int64_t rows_per_core, int64_t ub_tile_rows,
72	        int64_t rotary_mode)
73	    {
74	        totalRows_ = total_rows;
75	        D_ = D;
76	        halfD_ = half_d;
77	        rowsPerCore_ = rows_per_core;
78	        ubTileRows_ = ub_tile_rows;
79	        rotaryMode_ = rotary_mode;
80	
81	        coreIdx_ = static_cast<int64_t>(GetBlockIdx());
82	        rowStart_ = coreIdx_ * rowsPerCore_;
83	        rowEnd_ = (rowStart_ + rowsPerCore_ > totalRows_)
84	                    ? totalRows_ : (rowStart_ + rowsPerCore_);
85	        curCoreRows_ = rowEnd_ - rowStart_;
86	
87	        // Bind GM tensors
88	        int64_t totalElems = totalRows_ * D_;
89	        inputGm_.SetGlobalBuffer(
90	            reinterpret_cast<__gm__ dataType *>(input),
91	            static_cast<uint64_t>(totalElems));
92	        r1Gm_.SetGlobalBuffer(
93	            reinterpret_cast<__gm__ dataType *>(r1),
94	            static_cast<uint64_t>(totalElems));
95	        r2Gm_.SetGlobalBuffer(
96	            reinterpret_cast<__gm__ dataType *>(r2),
97	            static_cast<uint64_t>(totalElems));
98	        outputGm_.SetGlobalBuffer(
99	            reinterpret_cast<__gm__ dataType *>(output),
100	            static_cast<uint64_t>(totalElems));
101	
102	        // Initialize UB buffers
103	        int64_t tileElems = ubTileRows_ * D_;
104	        int64_t tileHalfElems = ubTileRows_ * halfD_;
105	
106	        pipe.InitBuffer(inQueue_, BUFFER_NUM,
107	                        static_cast<uint32_t>(tileElems * sizeof(dataType)));
108	        pipe.InitBuffer(outQueue_, BUFFER_NUM,
109	                        static_cast<uint32_t>(tileElems * sizeof(dataType)));
110	
111	        // FP32 compute buffers
112	        pipe.InitBuffer(inpFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
113	        pipe.InitBuffer(r1Fp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
114	        pipe.InitBuffer(r2Fp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
115	        pipe.InitBuffer(rotFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
116	
117	        // Auxiliary buffers for interleave mode
118	        if (rotaryMode_ == 1) {
119	            pipe.InitBuffer(evenBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
120	            pipe.InitBuffer(oddBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
121	        }
122	    }
123	
124	    __aicore__ inline void Process()
125	    {
126	        if (curCoreRows_ <= 0) { return; }
127	
128	        int64_t numTiles = (curCoreRows_ + ubTileRows_ - 1) / ubTileRows_;
129	
130	        for (int64_t tileIdx = 0; tileIdx < numTiles; ++tileIdx) {
131	            int64_t tileStart = tileIdx * ubTileRows_;
132	            int64_t tileEnd = (tileStart + ubTileRows_ > curCoreRows_)
133	                                ? curCoreRows_ : (tileStart + ubTileRows_);
134	            int32_t curRows = static_cast<int32_t>(tileEnd - tileStart);
135	            int32_t curElems = curRows * static_cast<int32_t>(D_);
136	            int32_t curHalfElems = curRows * static_cast<int32_t>(halfD_);
137	            int64_t globalOffset = (rowStart_ + tileStart) * D_;
138	
139	            CopyIn(globalOffset, curElems, curRows);
140	            Compute(curRows, curElems, curHalfElems, globalOffset);
141	            CopyOut(globalOffset, curElems, curRows);
142	        }
143	    }
144	
145	private:
146	    // ------------------------------------------------------------------
147	    // CopyIn: load input tile from GM to UB, cast to FP32
148	    // ------------------------------------------------------------------
149	    __aicore__ inline void CopyIn(
150	        int64_t globalOffset, int32_t curElems, int32_t curRows)
151	    {
152	        // Get FP32 TBuf pointers first (they will receive cast data)
153	        inpFp32Local_ = inpFp32Buf_.Get<float>();
154	        r1Fp32Local_ = r1Fp32Buf_.Get<float>();
155	        r2Fp32Local_ = r2Fp32Buf_.Get<float>();
156	        rotFp32Local_ = rotFp32Buf_.Get<float>();
157	
158	        // Load and cast input
159	        {
160	            LocalTensor<dataType> inTemp = inQueue_.AllocTensor<dataType>();
161	            LoadGmToUb(inTemp, inputGm_[globalOffset], curElems);
162	            inQueue_.EnQue(inTemp);
163	            LocalTensor<dataType> inDeq = inQueue_.DeQue<dataType>();
164	            if constexpr (std::is_same_v<dataType, float>) {
165	                // Direct reinterpret: inpFp32Local_ points to inpFp32Buf_, copy from queue
166	                DataCopy(inpFp32Local_, inDeq, static_cast<uint32_t>(curElems));
167	            } else {
168	                Cast(inpFp32Local_, inDeq, RoundMode::CAST_NONE, curElems);
169	                PipeBarrier<PIPE_V>();
170	            }
171	            inQueue_.FreeTensor(inDeq);
172	        }
173	        PipeBarrier<PIPE_ALL>();
174	
175	        // Load and cast r1
176	        {
177	            LocalTensor<dataType> r1Temp = inQueue_.AllocTensor<dataType>();
178	            LoadGmToUb(r1Temp, r1Gm_[globalOffset], curElems);
179	            inQueue_.EnQue(r1Temp);
180	            LocalTensor<dataType> r1Deq = inQueue_.DeQue<dataType>();
181	            if constexpr (std::is_same_v<dataType, float>) {
182	                DataCopy(r1Fp32Local_, r1Deq, static_cast<uint32_t>(curElems));
183	            } else {
184	                Cast(r1Fp32Local_, r1Deq, RoundMode::CAST_NONE, curElems);
185	                PipeBarrier<PIPE_V>();
186	            }
187	            inQueue_.FreeTensor(r1Deq);
188	        }
189	        PipeBarrier<PIPE_ALL>();
190	
191	        // Load and cast r2
192	        {
193	            LocalTensor<dataType> r2Temp = inQueue_.AllocTensor<dataType>();
194	            LoadGmToUb(r2Temp, r2Gm_[globalOffset], curElems);
195	            inQueue_.EnQue(r2Temp);
196	            LocalTensor<dataType> r2Deq = inQueue_.DeQue<dataType>();
197	            if constexpr (std::is_same_v<dataType, float>) {
198	                DataCopy(r2Fp32Local_, r2Deq, static_cast<uint32_t>(curElems));
199	            } else {
200	                Cast(r2Fp32Local_, r2Deq, RoundMode::CAST_NONE, curElems);
201	                PipeBarrier<PIPE_V>();
202	            }
203	            inQueue_.FreeTensor(r2Deq);
204	        }
205	        PipeBarrier<PIPE_ALL>();
206	    }
207	
208	    // ------------------------------------------------------------------
209	    // Compute: build rotated, compute output = input*r1 + rotated*r2
210	    // ------------------------------------------------------------------
211	    __aicore__ inline void Compute(
212	        int32_t curRows, int32_t curElems, int32_t curHalfElems,
213	        int64_t globalOffset)
214	    {
215	        if (rotaryMode_ == 0) {
216	            ComputeHalfMode(curRows, curElems, curHalfElems, globalOffset);
217	        } else {
218	            ComputeInterleaveMode(curRows, curElems, curHalfElems);
219	        }
220	        PipeBarrier<PIPE_ALL>();
221	    }
222	
223	    // ------------------------------------------------------------------
224	    // Half mode: rotated = concat(-input[halfD:], input[:halfD])
225	    // D is small (<=128), use simple per-element assignment for rotation
226	    // ------------------------------------------------------------------
227	    __aicore__ inline void ComputeHalfMode(
228	        int32_t curRows, int32_t curElems, int32_t curHalfElems,
229	        int64_t globalOffset)
230	    {
231	        int32_t D32 = static_cast<int32_t>(D_);
232	        int32_t halfD32 = static_cast<int32_t>(halfD_);
233	
234	        // Build rotated from inpFp32Local_ (already loaded and cast)
235	        // rotated[:, 0:halfD] = -inpFp32[:, halfD:D]
236	        // rotated[:, halfD:D] = inpFp32[:, 0:halfD]
237	        for (int32_t r = 0; r < curRows; ++r) {
238	            int32_t rowOff = r * D32;
239	            int32_t rowOffHalf = rowOff + halfD32;
240	            for (int32_t i = 0; i < halfD32; ++i) {
241	                rotFp32Local_(rowOff + i) = -inpFp32Local_(rowOffHalf + i);
242	                rotFp32Local_(rowOffHalf + i) = inpFp32Local_(rowOff + i);
243	            }
244	        }
245	        PipeBarrier<PIPE_ALL>();
246	
247	        // Compute: output = input * r1 + rotated * r2
248	        Mul(r1Fp32Local_, inpFp32Local_, r1Fp32Local_, curElems);
249	        PipeBarrier<PIPE_V>();
250	        Mul(r2Fp32Local_, rotFp32Local_, r2Fp32Local_, curElems);
251	        PipeBarrier<PIPE_V>();
252	        Add(rotFp32Local_, r1Fp32Local_, r2Fp32Local_, curElems);
253	        PipeBarrier<PIPE_V>();
254	    }
255	
256	    // ------------------------------------------------------------------
257	    // Interleave mode: extract even/odd + negate + merge
258	    // D is small (<=128), so scalar element access is acceptable for
259	    // the extraction and merge steps.  All arithmetic is vectorized.
260	    // ------------------------------------------------------------------
261	    __aicore__ inline void ComputeInterleaveMode(
262	        int32_t curRows, int32_t curElems, int32_t curHalfElems)
263	    {
264	        int32_t halfD32 = static_cast<int32_t>(halfD_);
265	        int32_t D32 = static_cast<int32_t>(D_);
266	
267	        LocalTensor<float> evenTmp = evenBuf_.Get<float>();
268	        LocalTensor<float> oddTmp = oddBuf_.Get<float>();
269	
270	        // Extract even (0,2,4,...) and odd (1,3,5,...) using scalar access
271	        // because D is small (max 128) and GatherMask has complex API constraints
272	        for (int32_t r = 0; r < curRows; ++r) {
273	            int32_t rowOffD = r * D32;
274	            int32_t rowOffHalf = r * halfD32;
275	            for (int32_t i = 0; i < halfD32; ++i) {
276	                evenTmp(rowOffHalf + i) = inpFp32Local_(rowOffD + 2 * i);
277	                oddTmp(rowOffHalf + i) = inpFp32Local_(rowOffD + 2 * i + 1);
278	            }
279	        }
280	        PipeBarrier<PIPE_ALL>();
281	
282	        // Negate odds (vectorized)
283	        Muls(oddTmp, oddTmp, -1.0f, curHalfElems);
284	        PipeBarrier<PIPE_V>();
285	
286	        // Merge: rotFp32[2*i] = oddTmp[i], rotFp32[2*i+1] = evenTmp[i]
287	        for (int32_t r = 0; r < curRows; ++r) {
288	            int32_t rowOffD = r * D32;
289	            int32_t rowOffHalf = r * halfD32;
290	            for (int32_t i = 0; i < halfD32; ++i) {
291	                rotFp32Local_(rowOffD + 2 * i) = oddTmp(rowOffHalf + i);
292	                rotFp32Local_(rowOffD + 2 * i + 1) = evenTmp(rowOffHalf + i);
293	            }
294	        }
295	        PipeBarrier<PIPE_ALL>();
296	
297	        // Compute: output = input * r1 + rotated * r2 (all vectorized)
298	        Mul(r1Fp32Local_, inpFp32Local_, r1Fp32Local_, curElems);
299	        PipeBarrier<PIPE_V>();
300	        Mul(r2Fp32Local_, rotFp32Local_, r2Fp32Local_, curElems);
301	        PipeBarrier<PIPE_V>();
302	        Add(rotFp32Local_, r1Fp32Local_, r2Fp32Local_, curElems);
303	        PipeBarrier<PIPE_V>();
304	    }
305	
306	    // ------------------------------------------------------------------
307	    // CopyOut: cast to output dtype, write to GM
308	    // ------------------------------------------------------------------
309	    __aicore__ inline void CopyOut(
310	        int64_t globalOffset, int32_t curElems, int32_t curRows)
311	    {
312	        // rotFp32Local_ holds the result in FP32
313	        LocalTensor<dataType> outTemp = outQueue_.AllocTensor<dataType>();
314	
315	        if constexpr (std::is_same_v<dataType, float>) {
316	            // Direct copy: results are already fp32
317	            DataCopy(outTemp, rotFp32Local_,
318	                     static_cast<uint32_t>(curElems));
319	        } else {
320	            // Cast fp32 → output dtype
321	            Cast(outTemp, rotFp32Local_, OutputCastMode<dataType>(), curElems);
322	            PipeBarrier<PIPE_V>();
323	        }
324	
325	        outQueue_.EnQue(outTemp);
326	        LocalTensor<dataType> outDeq = outQueue_.DeQue<dataType>();
327	        StoreUbToGm(outputGm_[globalOffset], outDeq, curElems);
328	        outQueue_.FreeTensor(outDeq);
329	        PipeBarrier<PIPE_ALL>();
330	    }
331	
332	    // Parameters
333	    int64_t totalRows_ = 0;
334	    int64_t D_ = 0;
335	    int64_t halfD_ = 0;
336	    int64_t rowsPerCore_ = 0;
337	    int64_t ubTileRows_ = 0;
338	    int64_t rotaryMode_ = 0;
339	    int64_t coreIdx_ = 0;
340	    int64_t rowStart_ = 0;
341	    int64_t rowEnd_ = 0;
342	    int64_t curCoreRows_ = 0;
343	
344	    // GM tensors
345	    GlobalTensor<dataType> inputGm_;
346	    GlobalTensor<dataType> r1Gm_;
347	    GlobalTensor<dataType> r2Gm_;
348	    GlobalTensor<dataType> outputGm_;
349	
350	    // Pipe and Queues
351	    TPipe pipe;
352	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue_;
353	    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue_;
354	
355	    // TBufs for compute (FP32)
356	    TBuf<TPosition::VECCALC> inpFp32Buf_;
357	    TBuf<TPosition::VECCALC> r1Fp32Buf_;
358	    TBuf<TPosition::VECCALC> r2Fp32Buf_;
359	    TBuf<TPosition::VECCALC> rotFp32Buf_;
360	    TBuf<TPosition::VECCALC> evenBuf_;      // for interleave even extraction
361	    TBuf<TPosition::VECCALC> oddBuf_;       // for interleave odd extraction
362	
363	    // Local tensors
364	    LocalTensor<float> inpFp32Local_;
365	    LocalTensor<float> r1Fp32Local_;
366	    LocalTensor<float> r2Fp32Local_;
367	    LocalTensor<float> rotFp32Local_;
368	};
369	
370	// =========================================================================
371	// Dtype dispatch helper
372	// =========================================================================
373	
374	template <typename... ExtraArgs>
375	__aicore__ inline void DispatchRotaryMul(
376	    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
377	    int64_t total_rows, int64_t D, int64_t half_d,
378	    int64_t rows_per_core, int64_t ub_tile_rows,
379	    int64_t rotary_mode, int64_t dtype_flag)
380	{
381	    if (dtype_flag == 0) {
382	        KernelRotaryMul<float> kernel;
383	        kernel.Init(input, r1, r2, output,
384	                    total_rows, D, half_d,
385	                    rows_per_core, ub_tile_rows,
386	                    rotary_mode);
387	        kernel.Process();
388	    } else if (dtype_flag == 1) {
389	        KernelRotaryMul<half> kernel;
390	        kernel.Init(input, r1, r2, output,
391	                    total_rows, D, half_d,
392	                    rows_per_core, ub_tile_rows,
393	                    rotary_mode);
394	        kernel.Process();
395	    } else {
396	        KernelRotaryMul<bfloat16_t> kernel;
397	        kernel.Init(input, r1, r2, output,
398	                    total_rows, D, half_d,
399	                    rows_per_core, ub_tile_rows,
400	                    rotary_mode);
401	        kernel.Process();
402	    }
403	}
404	
405	// =========================================================================
406	// Kernel entry points — one per dtype
407	// dtype_flag: 0=fp32, 1=fp16, 2=bf16
408	// =========================================================================
409	
410	extern "C" __global__ __aicore__ void rotary_mul(
411	    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
412	    int64_t total_rows, int64_t D, int64_t half_d,
413	    int64_t rows_per_core, int64_t ub_tile_rows,
414	    int64_t rotary_mode, int64_t dtype_flag)
415	{
416	    DispatchRotaryMul(
417	        input, r1, r2, output,
418	        total_rows, D, half_d,
419	        rows_per_core, ub_tile_rows,
420	        rotary_mode, dtype_flag);
421	}
