// HybridAttentionMaskPreparation AscendC kernel
// Generates hybrid attention masks (full causal + sliding window).
// All inputs are scalar parameters; output is a bool (uint8) mask tensor.
// Pure Vector operator, no Cube.

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Data movement helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void StoreUbToGm(
    const GlobalTensor<T> &dst,
    const LocalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// HybridAttentionMaskPreparation Kernel
// ---------------------------------------------------------------------------

class KernelHybridAttentionMaskPreparation {
public:
    __aicore__ inline void Init(
        GM_ADDR full_mask_gm, GM_ADDR swa_mask_gm,
        int64_t target_len, int64_t source_len, int64_t past_kv_len,
        int64_t rows_per_core, int64_t tile_s)
    {
        targetLen_ = target_len;
        sourceLen_ = source_len;
        pastKvLen_ = past_kv_len;
        rowsPerCore_ = rows_per_core;
        tileS_ = tile_s;

        coreIdx_ = static_cast<int64_t>(GetBlockIdx());
        rowStart_ = coreIdx_ * rowsPerCore_;
        rowEnd_ = (rowStart_ + rowsPerCore_ > targetLen_)
                   ? targetLen_ : (rowStart_ + rowsPerCore_);
        curCoreRows_ = rowEnd_ - rowStart_;

        // Bind GM tensors (2D [targetLen, sourceLen])
        uint64_t totalElems = static_cast<uint64_t>(targetLen_ * sourceLen_);
        fullMaskGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(full_mask_gm), totalElems);
        swaMaskGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(swa_mask_gm), totalElems);

        // Initialize UB buffers
        // int32 buffers for index arithmetic and comparison
        pipe.InitBuffer(sIdxBuf_, static_cast<uint32_t>(tileS_ * sizeof(int32_t)));
        pipe.InitBuffer(rowTiBuf_, static_cast<uint32_t>(tileS_ * sizeof(int32_t)));
        pipe.InitBuffer(cmpBuf_, static_cast<uint32_t>(tileS_ * sizeof(int32_t)));
        pipe.InitBuffer(oneBuf_, static_cast<uint32_t>(tileS_ * sizeof(int32_t)));
        // uint8 buffer for output row
        pipe.InitBuffer(fullRowBuf_, static_cast<uint32_t>(tileS_ * sizeof(uint8_t)));
        // uint8 buffer for zero SWA row
        pipe.InitBuffer(zeroRowBuf_, static_cast<uint32_t>(tileS_ * sizeof(uint8_t)));
    }

    __aicore__ inline void Process()
    {
        if (curCoreRows_ <= 0) { return; }

        int64_t numSTiles = (sourceLen_ + tileS_ - 1) / tileS_;

        for (int64_t sTile = 0; sTile < numSTiles; ++sTile) {
            int64_t sStart = sTile * tileS_;
            int64_t sEnd = (sStart + tileS_ > sourceLen_) ? sourceLen_ : (sStart + tileS_);
            int32_t curS = static_cast<int32_t>(sEnd - sStart);

            // Generate source index vector and constant buffers
            PrepareSTile(sStart, curS);

            for (int64_t r = 0; r < curCoreRows_; ++r) {
                int64_t ti = rowStart_ + r;
                ComputeRow(ti, sStart, curS);
            }
        }
    }

private:
    // ------------------------------------------------------------------
    // PrepareSTile: generate source index vector and constant buffers
    // ------------------------------------------------------------------
    __aicore__ inline void PrepareSTile(int64_t sStart, int32_t curS)
    {
        // Generate sIdx = [sStart, sStart+1, ..., sStart+curS-1] as int32
        LocalTensor<int32_t> sIdx = sIdxBuf_.Get<int32_t>();
        ArithProgression(sIdx, static_cast<int32_t>(sStart), 1, curS);

        // Fill oneBuf_ with 1 for mask conversion
        LocalTensor<int32_t> one = oneBuf_.Get<int32_t>();
        Duplicate(one, static_cast<int32_t>(1), curS);

        // Fill zeroRowBuf_ with 0 for SWA mask output
        LocalTensor<uint8_t> zeroRow = zeroRowBuf_.Get<uint8_t>();
        Duplicate(zeroRow, static_cast<uint8_t>(0), curS);
    }

    // ------------------------------------------------------------------
    // ComputeRow: generate mask row for target index ti
    // full_mask[ti, j] = (ti + past_kv_len < j) ? 1 : 0 for uint8
    // ------------------------------------------------------------------
    __aicore__ inline void ComputeRow(int64_t ti, int64_t sStart, int32_t curS)
    {
        // Fill rowTi with (ti + pastKvLen)
        LocalTensor<int32_t> rowTi = rowTiBuf_.Get<int32_t>();
        int32_t tiShifted = static_cast<int32_t>(ti + pastKvLen_);
        Duplicate(rowTi, tiShifted, curS);

        // Compare rowTi < sIdx (element-wise LT)
        LocalTensor<int32_t> sIdx = sIdxBuf_.Get<int32_t>();
        LocalTensor<int32_t> cmp = cmpBuf_.Get<int32_t>();
        Compare(cmp, rowTi, sIdx, CMPMODE::LT, curS);
        PipeBarrier<PIPE_V>();

        // Convert bitmask to 0/1: AND with 1
        LocalTensor<int32_t> one = oneBuf_.Get<int32_t>();
        And(cmp, cmp, one, curS);
        PipeBarrier<PIPE_V>();

        // Cast int32 → uint8 for output
        LocalTensor<uint8_t> fullRow = fullRowBuf_.Get<uint8_t>();
        Cast(fullRow, cmp, RoundMode::CAST_NONE, curS);
        PipeBarrier<PIPE_V>();

        // Write full mask row to GM
        int64_t fullOffset = ti * sourceLen_ + sStart;
        StoreUbToGm(fullMaskGm_[fullOffset], fullRow, curS);

        // Write zero row to SWA mask
        LocalTensor<uint8_t> zeroRow = zeroRowBuf_.Get<uint8_t>();
        int64_t swaOffset = ti * sourceLen_ + sStart;
        StoreUbToGm(swaMaskGm_[swaOffset], zeroRow, curS);
    }

    // Parameters
    int64_t targetLen_ = 0;
    int64_t sourceLen_ = 0;
    int64_t pastKvLen_ = 0;
    int64_t rowsPerCore_ = 0;
    int64_t tileS_ = 0;
    int64_t coreIdx_ = 0;
    int64_t rowStart_ = 0;
    int64_t rowEnd_ = 0;
    int64_t curCoreRows_ = 0;

    // GM tensors
    GlobalTensor<uint8_t> fullMaskGm_;
    GlobalTensor<uint8_t> swaMaskGm_;

    // UB buffers
    TPipe pipe;
    TBuf<TPosition::VECCALC> sIdxBuf_;
    TBuf<TPosition::VECCALC> rowTiBuf_;
    TBuf<TPosition::VECCALC> cmpBuf_;
    TBuf<TPosition::VECCALC> oneBuf_;
    TBuf<TPosition::VECCALC> fullRowBuf_;
    TBuf<TPosition::VECCALC> zeroRowBuf_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void hybrid_attention_mask_preparation(
    GM_ADDR full_mask, GM_ADDR swa_mask,
    int64_t target_len, int64_t source_len, int64_t past_kv_len,
    int64_t rows_per_core, int64_t tile_s)
{
    KernelHybridAttentionMaskPreparation kernel;
    kernel.Init(full_mask, swa_mask,
                target_len, source_len, past_kv_len,
                rows_per_core, tile_s);
    kernel.Process();
}
