// HybridAttentionMaskPreparation op_host
// Tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_hybrid_attention_mask_preparation.h"

namespace ascend_kernel {

// ---------------------------------------------------------------------------
// Helper: integer ceil division
// ---------------------------------------------------------------------------

static inline int64_t CeilDiv(int64_t a, int64_t b)
{
    if (b <= 0) { return 0; }
    return (a + b - 1) / b;
}

// ---------------------------------------------------------------------------
// Host function: hybrid_attention_mask_preparation
// ---------------------------------------------------------------------------

std::tuple<at::Tensor, at::Tensor> hybrid_attention_mask_preparation(
    int64_t batch_size,
    int64_t seq_length,
    int64_t past_key_values_length,
    int64_t num_attention_heads,
    int64_t swa_num_attention_heads,
    int64_t sliding_window)
{
    // --- Problem size ---
    int64_t target_len = seq_length;
    int64_t source_len = seq_length + past_key_values_length;
    int64_t total_elems = target_len * source_len;

    // --- Platform info ---
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) { coreNum = 32; }

    // --- UB tile size calculation ---
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // UB budget: sIdxBuf + rowTiBuf + cmpBuf + oneBuf (4x tileS * sizeof(int32_t))
    //           + fullRowBuf + zeroRowBuf (2x tileS * sizeof(uint8_t))
    // = tileS * (4*4 + 2*1) = tileS * 18 bytes
    int64_t ubPerTileElem = 18;
    int64_t maxTileS = static_cast<int64_t>(static_cast<double>(ubSize) * 0.8 / ubPerTileElem);
    // Clamp and align to 256
    int64_t tile_s = std::min<int64_t>(256, std::max<int64_t>(64, maxTileS));
    tile_s = (tile_s / 32) * 32;
    if (tile_s < 32) { tile_s = 32; }

    // --- Core-level tiling ---
    // Split target_len rows across cores
    int64_t usedCoreNum = std::min(coreNum, target_len);
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int64_t rows_per_core = CeilDiv(target_len, usedCoreNum);

    // --- Output allocation ---
    // Create 2D mask tensors [target_len, source_len] as uint8 (bool)
    auto options = at::TensorOptions()
                       .dtype(at::kByte)
                       .device(at::Device(DEVICE_TYPE));
    at::Tensor full_mask_out = at::zeros({target_len, source_len}, options);
    at::Tensor swa_mask_out = at::zeros({target_len, source_len}, options);

    // --- EXEC_KERNEL_CMD: all parameters must be left-values ---
    int64_t target_len_lv = target_len;
    int64_t source_len_lv = source_len;
    int64_t past_kv_len_lv = past_key_values_length;
    int64_t rows_per_core_lv = rows_per_core;
    int64_t tile_s_lv = tile_s;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(hybrid_attention_mask_preparation, blockDim,
                    full_mask_out, swa_mask_out,
                    target_len_lv, source_len_lv, past_kv_len_lv,
                    rows_per_core_lv, tile_s_lv);

    return std::make_tuple(full_mask_out, swa_mask_out);
}

}  // namespace ascend_kernel
