100	    {
101	        // Generate sIdx = [sStart, sStart+1, ..., sStart+curS-1] as int32
102	        LocalTensor<int32_t> sIdx = sIdxBuf_.Get<int32_t>();
103	        ArithProgression(sIdx, static_cast<int32_t>(sStart), 1, curS);
