// ---------------------------------------------------------------------------
// AscendC int32 vector helper: fill buffer with scalar value
// ---------------------------------------------------------------------------
__aicore__ inline void FillInt32Vec(
    LocalTensor<int32_t> &dst,
    int32_t value,
    int32_t count)
{
