            LocalTensor<int32_t> sIdx = sIdxBuf_.Get<int32_t>();
            int32_t sFullBlocks = curS / INT32_BLOCK;
            int32_t sTail = curS % INT32_BLOCK;
            if (sFullBlocks > 0) {
                ArithProgression(sIdx, static_cast<int32_t>(sStart), 1,
                                 sFullBlocks, INT32_BLOCK);
            }
            if (sTail > 0) {
                int32_t base = sFullBlocks * INT32_BLOCK;
                for (int32_t j = 0; j < sTail; ++j) {
                    sIdx(base + j) = static_cast<int32_t>(sStart + base + j);
                }
